:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #202c35;
  background: #f3f0e8;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #f3f0e8;
  background-image: radial-gradient(#d9d4c8 1px, transparent 1px);
  background-size: 18px 18px;
}

.card {
  width: min(100%, 620px);
  padding: clamp(22px, 5vw, 38px);
  background: #fffdf8;
  border: 1px solid #e2ded3;
  border-radius: 24px;
  box-shadow: 0 18px 55px #26374318;
}

.header { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 30px; }
.eyebrow { margin: 0 0 8px; color: #57746f; font-size: .78rem; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 0; font-size: clamp(1.65rem, 6vw, 2.25rem); letter-spacing: -.04em; }
.subtitle { margin: 8px 0 0; color: #657078; }

button {
  flex: none;
  min-height: 48px;
  padding: 0 18px;
  color: #fffdf8;
  background: #376b63;
  border: 0;
  border-radius: 12px;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s, transform .15s, box-shadow .15s;
}
button:hover { background: #28574f; box-shadow: 0 5px 12px #28574f2b; }
button:active { transform: translateY(2px); box-shadow: none; }
button:focus-visible, input:focus-visible { outline: 3px solid #e49a48; outline-offset: 3px; }

.board {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 76px;
  grid-template-rows: auto auto;
  gap: 10px;
}
.grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.cell {
  width: 100%;
  min-width: 0;
  aspect-ratio: 1;
  padding: 0;
  text-align: center;
  color: #202c35;
  background: #f1eee5;
  border: 2px solid #e2ded3;
  border-radius: 13px;
  font: inherit;
  font-size: clamp(1.1rem, 5vw, 1.55rem);
  font-weight: 700;
  appearance: textfield;
  transition: border-color .15s, background .15s, box-shadow .15s;
}
.cell::-webkit-inner-spin-button, .cell::-webkit-outer-spin-button { appearance: none; margin: 0; }
.cell:hover { border-color: #9bb8ae; background: #f8f6ef; }
.cell:focus { background: #fffdf8; border-color: #376b63; }
.row-sums { display: grid; grid-template-rows: repeat(4, 1fr); gap: 8px; }
.sum-box, .corner-total {
  min-height: 54px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 1px;
  color: #52616a;
  background: #e9eee8;
  border: 1px solid #dce5dd;
  border-radius: 12px;
}
.sum-label { font-size: .68rem; font-weight: 800; letter-spacing: .08em; color: #718079; }
.sum-value { font-size: 1.15rem; font-weight: 800; font-variant-numeric: tabular-nums; }
.sum-box.is-largest { color: #533b1e; background: #f8e6c9; border-color: #e8bd7c; box-shadow: inset 4px 0 #d78c37; }
.sum-box.is-largest .sum-label { color: #8c6029; }
.corner-total { color: #fffdf8; background: #344b55; border-color: #344b55; }
.corner-total .sum-label { color: #c8d6d4; }
.corner-total output { font-size: 1.15rem; font-weight: 800; font-variant-numeric: tabular-nums; }
.column-sums { grid-column: 1; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.hint { margin: 20px 0 0; color: #657078; font-size: .9rem; }

@media (max-width: 430px) {
  body { padding: 20px 12px; }
  .card { padding: 22px 16px; border-radius: 20px; }
  .header { align-items: flex-start; flex-direction: column; margin-bottom: 22px; }
  button { align-self: stretch; }
  .board { grid-template-columns: minmax(0, 1fr) 62px; gap: 7px; }
  .grid, .column-sums, .row-sums { gap: 6px; }
  .cell { border-radius: 10px; }
}

const grid = document.querySelector('#grid');
const rowSums = document.querySelector('#row-sums');
const columnSums = document.querySelector('#column-sums');
const grandTotal = document.querySelector('#grand-total');
const values = Array.from({ length: 4 }, () => Array(4).fill(0));
const rowOutputs = [];
const columnOutputs = [];

for (let row = 0; row < 4; row += 1) {
  for (let column = 0; column < 4; column += 1) {
    const input = document.createElement('input');
    input.className = 'cell';
    input.type = 'number';
    input.inputMode = 'numeric';
    input.min = '0';
    input.step = '1';
    input.value = '0';
    input.setAttribute('aria-label', `Row ${row + 1}, column ${column + 1}`);
    input.addEventListener('input', () => {
      const parsed = Number.parseInt(input.value, 10);
      values[row][column] = Number.isFinite(parsed) ? parsed : 0;
      updateSums();
    });
    grid.append(input);
  }

  const sum = document.createElement('div');
  sum.className = 'sum-box';
  sum.setAttribute('aria-label', `Row ${row + 1} sum`);
  sum.innerHTML = `<span class="sum-label">ROW ${row + 1}</span><output class="sum-value">0</output>`;
  rowSums.append(sum);
  rowOutputs.push(sum);
}

for (let column = 0; column < 4; column += 1) {
  const sum = document.createElement('div');
  sum.className = 'sum-box';
  sum.setAttribute('aria-label', `Column ${column + 1} sum`);
  sum.innerHTML = `<span class="sum-label">COL ${column + 1}</span><output class="sum-value">0</output>`;
  columnSums.append(sum);
  columnOutputs.push(sum);
}

function updateSums() {
  const rows = values.map(row => row.reduce((total, value) => total + value, 0));
  const columns = values[0].map((_, column) => values.reduce((total, row) => total + row[column], 0));
  const largest = Math.max(...rows);

  rowOutputs.forEach((box, index) => {
    box.querySelector('output').value = rows[index];
    box.classList.toggle('is-largest', rows[index] === largest);
  });
  columnOutputs.forEach((box, index) => { box.querySelector('output').value = columns[index]; });
  grandTotal.value = rows.reduce((total, value) => total + value, 0);
}

document.querySelector('#randomize').addEventListener('click', () => {
  const inputs = grid.querySelectorAll('input');
  inputs.forEach((input, index) => {
    const value = Math.floor(Math.random() * 9) + 1;
    values[Math.floor(index / 4)][index % 4] = value;
    input.value = String(value);
  });
  updateSums();
});

updateSums();
